import{_ as e,o as r,c as t,a0 as p}from"./chunks/framework.L_oL6aia.js";const n=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/shadowrocket.md","filePath":"guide/shadowrocket.md"}'),i={name:"guide/shadowrocket.md"};function o(l,a,c,h,s,d){return r(),t("div",null,[...a[0]||(a[0]=[p('<p>Shadowrocket 是 iOS 上非常流行的一款科学上网工具，界面简洁、配置灵活，尤其适合初学者。</p><h2 id="软件下载方式-需美区账号" tabindex="-1">软件下载方式（需美区账号） <a class="header-anchor" href="#软件下载方式-需美区账号" aria-label="Permalink to &quot;软件下载方式（需美区账号）&quot;">​</a></h2><p>Shadowrocket 是一款付费软件（2.99美元），仅在美区 App Store 上架，国区和其他来源存在大量山寨恶意应用，谨防误装。</p><p>官方正版下载地址：<br><a href="https://apps.apple.com/us/app/shadowrocket/id932747118" target="_blank" rel="noreferrer">https://apps.apple.com/us/app/shadowrocket/id932747118</a></p><h2 id="下载方式说明" tabindex="-1">下载方式说明 <a class="header-anchor" href="#下载方式说明" aria-label="Permalink to &quot;下载方式说明&quot;">​</a></h2><p>美区 Apple ID 自购（推荐）</p><p>*长期稳定，永久使用<br> *花费约 $2.99 一次性买断<br> *一次性买断，无后续付费，账号与应用永远绑定</p><p>购买地址：<a href="http://ios.mimy.cc" target="_blank" rel="noreferrer">http://ios.mimy.cc</a></p><p>登陆账号参考图：<br><img src="https://img.mimy.cc/appleid.webp" alt="Apple ID 图示"></p><h2 id="添加订阅链接" tabindex="-1">添加订阅链接 <a class="header-anchor" href="#添加订阅链接" aria-label="Permalink to &quot;添加订阅链接&quot;">​</a></h2><p>安装完 Shadowrocket 后，按照以下步骤添加订阅链接以获取节点：</p><p>1.打开官网点击仪表盘复制你的专属订阅链接<br> 2.打开 Shadowrocket 应用，点击右上角「+」按钮新增配置，类型选择 Subscribe<br> 3.将复制的链接粘贴到 URL 一栏，备注可自定义（如：放弃）<br> 4.点击右上角 完成</p><p>操作示意图：</p><p><img src="https://img.mimy.cc/IOS2.webp" alt="Apple ID 图示"><br><img src="https://img.mimy.cc/IOS3.webp" alt="Apple ID 图示"><br><img src="https://img.mimy.cc/fangqixhj111.webp" alt="Apple ID 图示"></p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>1.添加订阅成功后，应用会自动刷新并显示多个节点<br> 2. 选择任意节点<br> 3. 点击上方的开关按钮打开代理<br> 4. 出现 VPN 授权提示时点击“允许”，即可连接成功</p><h2 id="小火箭测试延迟-ping-教程" tabindex="-1">小火箭测试延迟（Ping）教程 <a class="header-anchor" href="#小火箭测试延迟-ping-教程" aria-label="Permalink to &quot;小火箭测试延迟（Ping）教程&quot;">​</a></h2><h2 id="方法一-单个节点测试延迟" tabindex="-1">方法一：单个节点测试延迟 <a class="header-anchor" href="#方法一-单个节点测试延迟" aria-label="Permalink to &quot;方法一：单个节点测试延迟&quot;">​</a></h2><p>1.打开 Shadowrocket<br> 2. 在首页节点列表中，长按任意一个节点<br> 3. 在弹出的菜单中，点击 “Ping” 或 “测试”<br> 4. 稍等片刻，即可显示该节点的延迟（单位：ms，越低越好）</p><h2 id="方法二-批量测试所有节点延迟" tabindex="-1">方法二：批量测试所有节点延迟 <a class="header-anchor" href="#方法二-批量测试所有节点延迟" aria-label="Permalink to &quot;方法二：批量测试所有节点延迟&quot;">​</a></h2><ol><li>打开 Shadowrocket，连通性测试模式选择CONNECT</li><li>在首页，点击“连通性测试”</li><li>应用会自动开始测试所有节点的延迟（右侧会显示 ms 数值）</li></ol><p>提示：<br> *绿色数字代表延迟较低（&lt; 100ms），通常速度更快<br> *红色或“超时”表示该节点无法连接或速度较慢<br> *建议优先选择延迟在 100-200ms 之间的节点使用</p><p><img src="https://img.mimy.cc/fangqixhj444.webp" alt="Apple ID 图示"><img src="https://img.mimy.cc/fangqixhj222.webp" alt="Apple ID 图示"></p>',23)])])}const b=e(i,[["render",o]]);export{n as __pageData,b as default};
